import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import axios from 'axios';
import toast from 'react-hot-toast';
import { FaUserPlus, FaUser, FaEnvelope, FaLock, FaStar } from 'react-icons/fa';

const Register = () => {
    const [formData, setFormData] = useState({ username: '', email: '', password: '', fullName: '' });
    const [loading, setLoading] = useState(false);
    const navigate = useNavigate();

    const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

    const handleSubmit = async (e) => {
        e.preventDefault();
        if (!formData.password || formData.password.length < 4) {
            toast.error('Password must be at least 4 characters');
            return;
        }
        setLoading(true);
        try {
            await axios.post('http://localhost:8081/api/auth/register', formData);
            toast.success('Registration successful! Please login.');
            navigate('/login');
        } catch (error) {
            toast.error(error.response?.data?.error || 'Registration failed');
        }
        setLoading(false);
    };

    return (
        <div className="min-h-screen d-flex align-items-center justify-content-center bg-gradient-to-br from-indigo-50 via-white to-purple-50 p-4">
            <div className="w-100" style={{ maxWidth: '420px' }}>
                <div className="text-center mb-4">
                    <div className="d-inline-flex align-items-center justify-content-center bg-gradient-to-r from-indigo-500 to-purple-600 shadow-lg shadow-indigo-200 rounded-4 mb-3" style={{ width: '64px', height: '64px' }}>
                        <FaStar size={28} className="text-white" />
                    </div>
                    <h1 className="fw-bold text-dark">Create Account</h1>
                    <p className="text-muted">Start tracking your progress today</p>
                </div>
                <div className="bg-white rounded-4 shadow-lg p-4 p-md-5 border">
                    <form onSubmit={handleSubmit}>
                        <div className="mb-3">
                            <label className="form-label fw-semibold small">Full Name</label>
                            <div className="position-relative">
                                <FaUser className="position-absolute top-50 start-0 translate-middle-y ms-3 text-muted" size={16} />
                                <input type="text" name="fullName" value={formData.fullName} onChange={handleChange} className="form-control ps-5 py-3 rounded-3 bg-light border-0" placeholder="Enter your full name" required />
                            </div>
                        </div>
                        <div className="mb-3">
                            <label className="form-label fw-semibold small">Username</label>
                            <div className="position-relative">
                                <FaUser className="position-absolute top-50 start-0 translate-middle-y ms-3 text-muted" size={16} />
                                <input type="text" name="username" value={formData.username} onChange={handleChange} className="form-control ps-5 py-3 rounded-3 bg-light border-0" placeholder="Choose a username" required />
                            </div>
                        </div>
                        <div className="mb-3">
                            <label className="form-label fw-semibold small">Email</label>
                            <div className="position-relative">
                                <FaEnvelope className="position-absolute top-50 start-0 translate-middle-y ms-3 text-muted" size={16} />
                                <input type="email" name="email" value={formData.email} onChange={handleChange} className="form-control ps-5 py-3 rounded-3 bg-light border-0" placeholder="Enter your email" required />
                            </div>
                        </div>
                        <div className="mb-4">
                            <label className="form-label fw-semibold small">Password</label>
                            <div className="position-relative">
                                <FaLock className="position-absolute top-50 start-0 translate-middle-y ms-3 text-muted" size={16} />
                                <input type="password" name="password" value={formData.password} onChange={handleChange} className="form-control ps-5 py-3 rounded-3 bg-light border-0" placeholder="Create a password (min 4 characters)" required minLength="4" />
                            </div>
                            <small className="text-muted">Minimum 4 characters</small>
                        </div>
                        <button type="submit" disabled={loading} className="btn btn-primary w-100 py-3 rounded-3 fw-semibold bg-gradient-to-r from-indigo-500 to-purple-600 border-0">
                            <FaUserPlus className="me-2" /> {loading ? 'Creating...' : 'Create Account'}
                        </button>
                    </form>
                    <div className="mt-4 text-center"><p className="text-muted small">Already have an account? <Link to="/login" className="text-indigo-600 fw-semibold text-decoration-none">Login</Link></p></div>
                </div>
            </div>
        </div>
    );
};

export default Register;
